from pathlib import Path
import re

p = Path('personalizza.html')
text = p.read_text(encoding='utf-8')

start = text.find('function buildGelateriaTemplate(logo, reviewUrl, backgroundDataUrl) {')
end = text.find('function buildPremiumTemplate(logo, reviewUrl, backgroundDataUrl, cfg) {', start)
assert start != -1 and end != -1, 'Template Gelateria non trovato'

new_fn = r'''function buildGelateriaTemplate(logo, reviewUrl, backgroundDataUrl) {
  const safeUrl = escapeHtml(reviewUrl);
  return `<!DOCTYPE html><html lang="it"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0,viewport-fit=cover"><meta name="theme-color" content="#111111"><title>Recensioni</title><style>
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}body{min-height:100vh;min-height:100dvh;overflow-x:hidden;background:#000;color:#fff}.scene-original{position:fixed;inset:0;width:100%;height:100%;object-fit:contain;object-position:center bottom;z-index:0;pointer-events:none;background:#000}.pagina{position:relative;z-index:2;min-height:100vh;min-height:100dvh;display:flex;align-items:flex-start;justify-content:center;padding:max(10px,env(safe-area-inset-top)) 16px 118px}.card{width:min(100%,530px);text-align:center;padding:0 8px 14px}.logo{display:block;width:min(285px,82%);max-height:150px;object-fit:contain;margin:0 auto 18px;padding:7px 10px;border-radius:20px;background:rgba(255,255,255,.12);filter:drop-shadow(0 0 10px rgba(255,255,255,.24)) drop-shadow(0 10px 24px rgba(0,0,0,.45))}.eyebrow{text-transform:uppercase;letter-spacing:.14em;font-size:14px;font-weight:900;color:#fff;margin:0 0 15px;text-shadow:0 4px 14px rgba(0,0,0,.82)}.messaggio-box{background:rgba(255,255,255,.70);color:#493340;border:1px solid rgba(255,255,255,.62);border-radius:19px;padding:15px 16px;margin:0 auto 21px;box-shadow:0 8px 22px rgba(90,45,72,.18);backdrop-filter:blur(2px)}.messaggio{margin:0;font-size:17px;line-height:1.46;font-weight:680}.bottone-google{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;min-height:62px;width:100%;border-radius:18px;text-decoration:none;color:#fff;font-weight:900;font-size:17px;padding:14px 18px;background:linear-gradient(135deg,#d55791,#58aeb1 54%,#d55791);box-shadow:0 16px 35px rgba(70,35,59,.30),inset 0 1px 0 rgba(255,255,255,.28);border:1px solid rgba(255,255,255,.32);animation:gelPulse 2.8s ease-in-out infinite}.bottone-google:before{content:"";position:absolute;top:-20%;left:-45%;width:34%;height:140%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.42),transparent);transform:skewX(-20deg);animation:gelShine 3.6s ease-in-out infinite}.bottone-google:after{content:"✦";position:absolute;right:18px;font-size:18px;color:#fff4bc;text-shadow:0 0 10px rgba(255,255,255,.88);animation:gelSpark 1.8s ease-in-out infinite}.stelle{margin-top:18px;font-size:30px;letter-spacing:.16em;color:#ffd85d;text-shadow:0 3px 9px rgba(0,0,0,.42)}@keyframes gelShine{0%,55%{left:-45%;opacity:0}60%{opacity:1}85%{left:120%;opacity:1}100%{left:120%;opacity:0}}@keyframes gelPulse{50%{transform:scale(1.018)}}@keyframes gelSpark{50%{opacity:1;transform:scale(1.15) rotate(12deg)}}footer{position:fixed;z-index:6;right:max(18px,env(safe-area-inset-right));bottom:max(16px,env(safe-area-inset-bottom));margin:0;font-size:11px;font-weight:650;color:#fff;text-align:right;text-shadow:0 3px 10px rgba(0,0,0,.95)}footer strong{display:block;color:#fff;font-size:23px;line-height:1.05;font-weight:950;letter-spacing:.02em}@media(max-width:640px){.pagina{padding-top:max(8px,env(safe-area-inset-top));padding-bottom:124px}.logo{width:min(270px,82%);max-height:142px;margin-bottom:16px}.messaggio{font-size:16px}.eyebrow{font-size:13px}.bottone-google{min-height:58px;font-size:16px}.stelle{font-size:28px}}@media (orientation:landscape) and (max-height:680px){.scene-original{object-fit:contain;object-position:left center}.pagina{min-height:100dvh;align-items:center;padding:10px 16px 50px}.card{width:min(100%,900px);display:grid;grid-template-columns:minmax(125px,.58fr) minmax(0,1.42fr);grid-template-areas:"logo eyebrow" "logo message" "logo button" "logo stars";align-items:center;column-gap:20px;row-gap:8px;padding:0}.logo{grid-area:logo;width:min(220px,100%);max-height:min(29vh,116px);margin:0 auto;padding:6px 9px;border-radius:17px}.eyebrow{grid-area:eyebrow;margin:0;font-size:12px;line-height:1.2;letter-spacing:.12em}.messaggio-box{grid-area:message;margin:0;padding:9px 12px;border-radius:14px}.messaggio{font-size:14px;line-height:1.32}.bottone-google{grid-area:button;min-height:48px;font-size:15px;padding:8px 14px;border-radius:14px}.stelle{grid-area:stars;margin-top:1px;font-size:24px;line-height:1}footer{right:14px;bottom:9px;font-size:9px}footer strong{font-size:18px}}@media(prefers-reduced-motion:reduce){.bottone-google,.bottone-google:before,.bottone-google:after{animation:none!important}}</style></head><body><img class="scene-original" src="${backgroundDataUrl}" alt=""><main class="pagina"><section class="card"><img class="logo" src="${logo}" alt="Logo attività"><div class="eyebrow">Ti è piaciuto il nostro gelato?</div><div class="messaggio-box"><p class="messaggio">La tua opinione rende tutto ancora più dolce. Raccontaci la tua esperienza! Bastano 2 secondi!</p></div><a class="bottone-google" href="${safeUrl}" target="_blank" rel="noopener noreferrer">Recensione Google</a><div class="stelle">★★★★★</div><footer>Powered by <strong>Tapreputa</strong></footer></section></main></body></html>`;
}

'''

text = text[:start] + new_fn + text[end:]
text = re.sub(r'tap-premium-polish\.css\?v=\d+', 'tap-premium-polish.css?v=15', text, count=1)
p.write_text(text, encoding='utf-8')

out = p.read_text(encoding='utf-8')
assert 'scene-fill' not in out[out.find('function buildGelateriaTemplate'):out.find('function buildPremiumTemplate')]
assert 'cup-brand' not in out[out.find('function buildGelateriaTemplate'):out.find('function buildPremiumTemplate')]
assert '<img class="scene-original"' in out
assert 'object-fit:contain' in out
print('Gelateria ripristinata: sfondo singolo, senza blur e senza sovrapposizioni sulle coppette')
